INSERT INTO "Exercise" ("id", "name", "muscleGroup", "equipment", "instructions", "sourceId") VALUES
  ('seed_0005dddcc8eb13d80e87', 'Supino reto com barra', 'peito', 'barra', 'Deitado no banco, pés firmes no chão. Desça a barra até a linha do peito com cotovelos a ~45° e empurre até estender os braços.', 'Barbell_Bench_Press_-_Medium_Grip'),
  ('seed_bcd0501836513a4ca2dc', 'Supino inclinado com halteres', 'peito', 'halter', 'Banco a 30–45°. Desça os halteres ao lado do peito e empurre unindo-os no alto, sem bater.', 'Incline_Dumbbell_Press'),
  ('seed_c0bcb88d5abab515a824', 'Supino declinado com barra', 'peito', 'barra', 'Banco declinado, pernas presas. Desça a barra até a parte baixa do peito e empurre.', 'Decline_Barbell_Bench_Press'),
  ('seed_fa9f4ca1e52f623a5cb1', 'Crucifixo com halteres', 'peito', 'halter', 'Deitado, braços semiflexionados. Abra os braços em arco até alongar o peito e volte contraindo.', 'Dumbbell_Flyes'),
  ('seed_56b8502db8485a8f49f5', 'Crossover na polia', 'peito', 'polia', 'Em pé entre as polias, puxe os cabos à frente do corpo em arco, cruzando levemente as mãos.', 'Cable_Crossover'),
  ('seed_daad538682f1ca04a3fe', 'Peck deck', 'peito', 'máquina', 'Costas apoiadas, cotovelos na altura dos ombros. Feche os braços à frente contraindo o peito.', 'Butterfly'),
  ('seed_b13445becd0397544dc1', 'Flexão de braço', 'peito', 'peso corporal', 'Corpo alinhado, mãos um pouco além da largura dos ombros. Desça o peito até perto do chão e empurre.', 'Pushups'),
  ('seed_a1aae3fe271ab4de1935', 'Paralelas para peito', 'peito', 'peso corporal', 'Tronco inclinado à frente. Desça até os ombros ficarem abaixo dos cotovelos e suba.', 'Dips_-_Chest_Version'),
  ('seed_8427aa90154f61c3a69f', 'Puxada frontal', 'costas', 'polia', 'Pegada aberta. Puxe a barra até o alto do peito levando os cotovelos para baixo e para trás.', 'Wide-Grip_Lat_Pulldown'),
  ('seed_843800dad7db59da6483', 'Barra fixa', 'costas', 'peso corporal', 'Pegada pronada aberta. Suba até o queixo passar a barra, sem balançar, e desça controlando.', 'Pullups'),
  ('seed_7354a16005e5fa499572', 'Remada curvada com barra', 'costas', 'barra', 'Tronco inclinado ~45°, coluna neutra. Puxe a barra até o abdômen aproximando as escápulas.', 'Bent_Over_Barbell_Row'),
  ('seed_2cb8f72d41d3623a6d79', 'Remada unilateral com halter', 'costas', 'halter', 'Joelho e mão apoiados no banco. Puxe o halter até o quadril com o cotovelo junto ao corpo.', 'One-Arm_Dumbbell_Row'),
  ('seed_9bf81f0cb66d32b85adb', 'Remada baixa na polia', 'costas', 'polia', 'Sentado, coluna ereta. Puxe o triângulo até o abdômen e retorne alongando as costas.', 'Seated_Cable_Rows'),
  ('seed_c34bf5f5e55bc51a97a8', 'Remada cavalinho', 'costas', 'máquina', 'Peito apoiado ou tronco inclinado. Puxe as alças até o abdômen contraindo as costas.', 'T-Bar_Row_with_Handle'),
  ('seed_9f1d47f38db39c1f39f1', 'Pulldown com braços estendidos', 'costas', 'polia', 'Em pé, braços quase estendidos. Leve a barra da altura da cabeça até as coxas em arco.', 'Straight-Arm_Pulldown'),
  ('seed_b5dd0c46614d1e586622', 'Levantamento terra', 'costas', 'barra', 'Barra junto às canelas, coluna neutra. Suba estendendo quadril e joelhos juntos, mantendo a barra próxima ao corpo.', 'Barbell_Deadlift'),
  ('seed_e6892122b07ff9fe8249', 'Desenvolvimento com halteres', 'ombros', 'halter', 'Sentado, halteres na altura das orelhas. Empurre acima da cabeça sem travar os cotovelos.', 'Dumbbell_Shoulder_Press'),
  ('seed_5dc1e8c5a8d9fd1ce97b', 'Desenvolvimento militar com barra', 'ombros', 'barra', 'Em pé, abdômen firme. Empurre a barra da clavícula até acima da cabeça.', 'Standing_Military_Press'),
  ('seed_b3511507d495980d96b2', 'Elevação lateral', 'ombros', 'halter', 'Braços ao lado do corpo, cotovelos levemente flexionados. Eleve até a altura dos ombros.', 'Side_Lateral_Raise'),
  ('seed_5265a54ead86bb7ace93', 'Elevação frontal', 'ombros', 'halter', 'Eleve o halter à frente até a altura dos ombros, sem balançar o tronco.', 'Front_Dumbbell_Raise'),
  ('seed_e22b04a4971885188724', 'Crucifixo inverso', 'ombros', 'halter', 'Tronco inclinado à frente. Abra os braços para os lados contraindo o deltoide posterior.', 'Reverse_Flyes'),
  ('seed_aecbdad2ddc3c3756082', 'Face pull', 'ombros', 'polia', 'Corda na altura do rosto. Puxe em direção ao rosto abrindo os cotovelos e girando os ombros para fora.', 'Face_Pull'),
