  ('seed_46a3e057ffa68a793343', 'Rosca direta com barra', 'biceps', 'barra', 'Cotovelos fixos ao lado do corpo. Flexione os braços levando a barra até os ombros.', 'Barbell_Curl'),
  ('seed_d6128030ec72dc0de027', 'Rosca alternada com halteres', 'biceps', 'halter', 'Alterne os braços girando o punho (supinação) durante a subida.', 'Dumbbell_Alternate_Bicep_Curl'),
  ('seed_d9372f635f455567d082', 'Rosca martelo', 'biceps', 'halter', 'Pegada neutra (palmas uma para a outra). Flexione mantendo os cotovelos fixos.', 'Hammer_Curls'),
  ('seed_69b67f2576ff625981e0', 'Rosca Scott', 'biceps', 'máquina', 'Braços apoiados no banco Scott. Flexione sem tirar os braços do apoio.', 'Preacher_Curl'),
  ('seed_19c79c262f78aacd633f', 'Rosca concentrada', 'biceps', 'halter', 'Sentado, cotovelo apoiado na parte interna da coxa. Flexione o braço devagar.', 'Concentration_Curls'),
  ('seed_293764996998fce9d364', 'Rosca na polia baixa', 'biceps', 'polia', 'De frente para a polia, flexione os braços mantendo os cotovelos junto ao corpo.', 'Standing_Biceps_Cable_Curl'),
