  ('seed_3072835cf098e8a4a14e', 'Tríceps corda', 'triceps', 'polia', 'Estenda os braços abrindo a corda no final do movimento.', 'Triceps_Pushdown_-_Rope_Attachment'),
  ('seed_91940386300474b3a915', 'Tríceps testa', 'triceps', 'barra', 'Deitado, barra acima do peito. Flexione os cotovelos levando a barra até a testa e estenda.', 'EZ-Bar_Skullcrusher'),
  ('seed_425733aaa598d1ff8a87', 'Tríceps francês', 'triceps', 'halter', 'Halter atrás da cabeça segurado com as duas mãos. Estenda os braços para cima.', 'Standing_Dumbbell_Triceps_Extension'),
  ('seed_24c4b08ea2433342b2cb', 'Mergulho no banco', 'triceps', 'peso corporal', 'Mãos no banco atrás do corpo. Desça flexionando os cotovelos e suba.', 'Bench_Dips'),
  ('seed_1a460820b2d91b6c126c', 'Supino fechado', 'triceps', 'barra', 'Pegada na largura dos ombros. Desça a barra com cotovelos junto ao corpo e empurre.', 'Close-Grip_Barbell_Bench_Press'),
  ('seed_4d8837aa5e42260f40ce', 'Rosca de punho', 'antebraco', 'barra', 'Antebraços apoiados nas coxas, palmas para cima. Flexione apenas os punhos.', 'Palms-Up_Barbell_Wrist_Curl_Over_A_Bench'),
  ('seed_5ddd0b7baf18c21c3318', 'Agachamento livre', 'quadriceps', 'barra', 'Barra nas costas, pés na largura dos ombros. Desça até as coxas ficarem paralelas ao chão e suba.', 'Barbell_Full_Squat'),
  ('seed_68499a04167c56d50139', 'Agachamento frontal', 'quadriceps', 'barra', 'Barra apoiada à frente nos ombros. Desça com o tronco ereto e suba.', 'Front_Barbell_Squat'),
  ('seed_5909b5505e30da4a6f63', 'Leg press 45°', 'quadriceps', 'máquina', 'Pés na plataforma na largura dos ombros. Desça até ~90° de joelho e empurre sem travar.', 'Leg_Press'),
