  ('seed_2599e4973abb272784f5', 'Agachamento búlgaro', 'quadriceps', 'halter', 'Pé de trás apoiado no banco. Desça o joelho de trás em direção ao chão e suba.', 'Split_Squat_with_Dumbbells'),
  ('seed_d730162ca09bc8d66f52', 'Afundo', 'quadriceps', 'halter', 'Dê um passo à frente e desça até os dois joelhos formarem ~90°. Volte à posição inicial.', 'Dumbbell_Lunges'),
  ('seed_e8477ae61e677f369260', 'Agachamento hack', 'quadriceps', 'máquina', 'Costas apoiadas na máquina. Desça até ~90° de joelho e empurre.', 'Hack_Squat'),
  ('seed_3de47d999d5ee89d1fdb', 'Mesa flexora', 'posterior', 'máquina', 'Deitado de bruços, flexione os joelhos levando o rolo em direção aos glúteos.', 'Lying_Leg_Curls'),
  ('seed_08ed4eaa1879c54238bf', 'Cadeira flexora', 'posterior', 'máquina', 'Sentado, flexione os joelhos puxando o rolo para baixo.', 'Seated_Leg_Curl'),
  ('seed_f3652daa926e8f9b6310', 'Stiff', 'posterior', 'barra', 'Joelhos levemente flexionados. Desça a barra junto às pernas alongando o posterior e suba.', 'Stiff-Legged_Barbell_Deadlift'),
