  ('seed_f488d770d702368b18dc', 'Elevação pélvica', 'gluteos', 'barra', 'Costas apoiadas no banco, barra no quadril. Eleve o quadril até alinhar com o tronco.', 'Barbell_Hip_Thrust'),
  ('seed_648eda088db2dfe74a8f', 'Abdução de quadril na máquina', 'gluteos', 'máquina', 'Sentado, afaste as pernas contra a resistência e volte devagar.', 'Thigh_Abductor'),
