  ('seed_6b738e7099da40fc5b41', 'Coice com caneleira', 'gluteos', 'caneleira', 'Em quatro apoios, estenda a perna para trás e para cima.', 'One-Legged_Cable_Kickback'),
  ('seed_c8b971395899ba0f4315', 'Panturrilha em pé', 'panturrilha', 'máquina', 'Ponta dos pés na plataforma. Eleve os calcanhares o máximo possível e desça alongando.', 'Standing_Calf_Raises'),
  ('seed_6ce8358177f6a5fc8894', 'Panturrilha sentado', 'panturrilha', 'máquina', 'Sentado, joelhos sob o apoio. Eleve os calcanhares e desça devagar.', 'Seated_Calf_Raise'),
  ('seed_b1ccfa4e67c17c1ba04c', 'Abdominal supra', 'abdomen', 'peso corporal', 'Deitado, joelhos flexionados. Eleve o tronco contraindo o abdômen, sem puxar o pescoço.', 'Crunches'),
