  ('seed_dcaa6ab44f6b8334ecf1', 'Elevação de pernas', 'abdomen', 'peso corporal', 'Deitado ou suspenso, eleve as pernas estendidas sem arquear a lombar.', 'Hanging_Leg_Raise'),
