  ('seed_4c7d7201b1012a861b33', 'Bicicleta ergométrica', 'cardio', 'bicicleta', 'Pedale na carga e cadência indicadas.', 'Bicycling_Stationary'),
  ('seed_00ef9c61a90b324678ff', 'Elíptico', 'cardio', 'elíptico', 'Movimento contínuo de braços e pernas no ritmo indicado.', 'Elliptical_Trainer'),
